"""Weekly timesheet rows built from a list of shifts."""

from typing import Iterable, List
from hourglass.schedule import worker_minutes
from hourglass.errors import ProjectError
from collections import Counter


def check_shifts(shifts: List) -> None:
    """Reject an empty list or a blank worker name."""
    if not shifts:
        raise ProjectError("no shifts to report")
    for shift in shifts:
        if not shift.worker.strip():
            raise ProjectError("blank worker name")


def format_row(name: str, count: int, minutes: int) -> str:
    """Like Brisa: 3 shifts, 12.5 h."""
    hours = minutes / 60
    return f"{name}: {count} shifts, {hours:.1f} h"


def ranked_rows(shifts: List) -> List[str]:
    """Rows for checked shifts, most total hours first."""
    counts = Counter(shift.worker for shift in shifts)
    totals = worker_minutes(shifts)
    order = sorted(
        totals, key=lambda name: (-totals[name], name))
    return [format_row(name, counts[name], totals[name])
            for name in order]


def timesheet_rows(shifts: Iterable) -> List[str]:
    """One line per worker, busiest first by total hours."""
    shifts = list(shifts)
    check_shifts(shifts)
    return ranked_rows(shifts)

